from __future__ import annotations
from fastapi import FastAPI, HTTPException
from fastapi.responses import HTMLResponse, PlainTextResponse
from src.macrofund.engine import run_engine
app=FastAPI(title="AI Global Macro Hedge Fund Engine",version="0.1.0",description="Systematic global-macro regime, signal, portfolio and backtest research engine.")
DASHBOARD='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Global Macro Hedge Fund Engine</title><style>:root{--bg:#07100f;--panel:#0c1715;--line:#20352f;--text:#f0f7f4;--muted:#8fa69e;--accent:#74f2b0;--blue:#80b7ff;--red:#ff8c8c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 0%,rgba(116,242,176,.08),transparent 28%),var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.shell{max-width:1240px;margin:auto;padding:28px 22px 70px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:46px}.brand{font-weight:850}.links a{color:var(--muted);text-decoration:none;margin-left:14px}.hero{display:grid;grid-template-columns:1.4fr .8fr;gap:20px}.eyebrow{color:var(--accent);text-transform:uppercase;letter-spacing:.16em;font-size:10px;font-weight:800}h1{font-size:clamp(42px,6vw,72px);line-height:.98;letter-spacing:-.055em;margin:12px 0 18px}.lede{max-width:760px;color:#a8bbb4;line-height:1.7}.card{border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.026),rgba(255,255,255,.009));border-radius:18px;padding:18px}.regime{font-size:32px;font-weight:850;letter-spacing:-.04em;color:var(--accent);margin:8px 0}.small{color:var(--muted);font-size:11px;line-height:1.5}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.metric .v{font-size:24px;font-weight:850;margin-top:7px}.label{font-size:9px;text-transform:uppercase;letter-spacing:.09em;color:#71877f}.grid{display:grid;grid-template-columns:1.3fr .7fr;gap:14px}.section{margin-top:14px}h2{font-size:16px;margin:0 0 13px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px 8px;border-bottom:1px solid #192a25;text-align:right}th:first-child,td:first-child{text-align:left}.long{color:var(--accent)}.short{color:var(--red)}.neutral{color:var(--muted)}.bar{height:8px;background:#162722;border-radius:99px;overflow:hidden}.bar span{height:100%;display:block;background:var(--blue)}pre{white-space:pre-wrap;color:#b8ccc4;font:12px/1.7 ui-monospace,monospace}.error{border:1px solid #6e3535;background:#241313;color:#ffc4c4;padding:16px;border-radius:14px}@media(max-width:850px){.hero,.grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}@media(max-width:480px){.metrics{grid-template-columns:1fr}}</style></head><body><div class="shell"><div class="top"><div class="brand">AI Global Macro Hedge Fund Engine</div><div class="links"><a href="/docs">API</a><a href="/memo">Memo</a></div></div><div class="hero"><div><div class="eyebrow">Systematic cross-asset macro research</div><h1>Regime → signals → risk → portfolio.</h1><div class="lede">A transparent global-macro research engine combining economic regime detection, cross-asset momentum, liquidity, volatility targeting and walk-forward portfolio simulation.</div></div><div class="card"><div class="label">Current macro regime</div><div id="regime" class="regime">Loading…</div><div id="conf" class="small"></div></div></div><div id="content"><div class="card section">Loading live macro and market data…</div></div></div><script>function p(x){return(100*Number(x)).toFixed(1)+'%'}function n(x){return Number(x).toFixed(2)}fetch('/snapshot').then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(d=>{const rg=d.regime;document.getElementById('regime').textContent=rg.regime;document.getElementById('conf').textContent='As of '+d.as_of+' · cluster confidence '+(rg.confidence==null?'n/a':p(rg.confidence));const bt=d.backtest.strategy,bm=d.backtest.benchmark_60_40;let rows=d.signals.map(x=>`<tr><td><b>${x.symbol}</b><div class="small">${x.asset}</div></td><td class="${x.direction.toLowerCase()}">${x.direction}</td><td>${x.score.toFixed(2)}</td><td>${p(x.momentum_12m)}</td><td>${p(x.weight)}</td></tr>`).join('');let weights=Object.entries(d.portfolio.weights).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).map(([k,v])=>`<div style="margin:11px 0"><div style="display:flex;justify-content:space-between"><span>${k}</span><b class="${v>=0?'long':'short'}">${p(v)}</b></div><div class="bar"><span style="width:${Math.min(100,Math.abs(v)*250)}%"></span></div></div>`).join('');document.getElementById('content').innerHTML=`<div class="metrics"><div class="card metric"><div class="label">Growth</div><div class="v">${n(rg.growth)}</div></div><div class="card metric"><div class="label">Inflation</div><div class="v">${n(rg.inflation)}</div></div><div class="card metric"><div class="label">Liquidity</div><div class="v">${n(rg.liquidity)}</div></div><div class="card metric"><div class="label">Risk</div><div class="v">${n(rg.risk)}</div></div></div><div class="grid"><section class="card"><h2>Cross-asset signal book</h2><table><thead><tr><th>Asset</th><th>View</th><th>Score</th><th>12m mom.</th><th>Weight</th></tr></thead><tbody>${rows}</tbody></table></section><section class="card"><h2>Portfolio exposure</h2>${weights}<div class="small">Gross ${p(d.portfolio.gross_exposure)} · Net ${p(d.portfolio.net_exposure)}</div></section></div><div class="metrics"><div class="card metric"><div class="label">Backtest CAGR</div><div class="v">${p(bt.cagr||0)}</div></div><div class="card metric"><div class="label">Sharpe</div><div class="v">${n(bt.sharpe||0)}</div></div><div class="card metric"><div class="label">Max drawdown</div><div class="v">${p(bt.max_drawdown||0)}</div></div><div class="card metric"><div class="label">60/40 CAGR</div><div class="v">${p(bm.cagr||0)}</div></div></div><section class="card section"><h2>Investment committee memo</h2><pre>${d.memo.replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}</pre></section>`}).catch(e=>{document.getElementById('content').innerHTML=`<div class="error"><b>Data engine unavailable.</b><br>${e.message}<br><br>Check external provider connectivity or API logs.</div>`})</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard():return DASHBOARD
@app.get('/health')
def health():return {'status':'ok'}
@app.get('/snapshot')
def snapshot(refresh:bool=False):
    try:return run_engine(force=refresh)
    except Exception as exc:raise HTTPException(status_code=503,detail=str(exc)) from exc
@app.get('/regime')
def regime():return snapshot()['regime']
@app.get('/signals')
def signals():return snapshot()['signals']
@app.get('/portfolio')
def portfolio():return snapshot()['portfolio']
@app.get('/backtest')
def backtest():return snapshot()['backtest']
@app.get('/memo',response_class=PlainTextResponse)
def memo():return snapshot()['memo']
